  "deliverable": {
    "theme": "{argument name="interface theme" default="futuristic product scanning interface"}",
    "result": "technical diagnostics visualization screen",
    "finish": "{argument name="quality finish" default="ultra clean, ultra clear, 8K"}"
  }
}

